import sys

def solve():
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        X = int(input_data[0])
    except ValueError:
        return

    n = 1
    fact = 1

    # Since X >= 2, N >= 2.
    # We can start checking from N=1, but since X >= 2, N will be at least 2.
    # Actually, let's just loop.

    while fact < X:
        n += 1
        fact *= n

    if fact == X:
        print(n)
    else:
        # This part should theoretically not be reached given the problem statement guarantees.
        # But if X was not a factorial, this would be the logic.
        # Given the guarantee, we can just print n.
        pass

if __name__ == '__main__':
    solve()

